"""Reads and writes the checked-in upstream inventory manifest (`spock-inventory.toml`).

On disk, each upstream class is a top-level table keyed by its fully-qualified name, with a
`features` sub-table mapping feature name to body hash. In memory, `load_manifest` returns the
shape the rest of the tooling consumes: `{"upstream": {...}, "classes": [...], "excluded": {...}}`.
"""
import tomllib
from pathlib import Path

MANIFEST_PATH = Path(__file__).parents[2] / "_docs" / "test-coverage" / "spock-inventory.toml"

_HEADER = "# Generated by .github/test-coverage/inventory.py. Do not edit by hand.\n"
_CLASS_FIELDS = ("path", "base", "recipe", "area")
_ESCAPES = {'"': '\\"', "\\": "\\\\", "\b": "\\b", "\t": "\\t", "\n": "\\n", "\f": "\\f", "\r": "\\r"}


def _quote(value: str) -> str:
    out = []
    for ch in value:
        if ch in _ESCAPES:
            out.append(_ESCAPES[ch])
        elif ord(ch) < 0x20 or ord(ch) == 0x7F:
            out.append(f"\\u{ord(ch):04x}")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def dumps_manifest(manifest: dict) -> str:
    upstream = manifest["upstream"]
    lines = [
        _HEADER.rstrip("\n"),
        f"excluded_classes = {manifest['excluded']['classes']}",
        "",
        "[upstream]",
        *(f"{field} = {_quote(upstream[field])}" for field in ("repo", "ref", "sha", "generated_at")),
    ]
    for spec_class in manifest["classes"]:
        key = _quote(spec_class["key"])
        lines += ["", f"[{key}]"]
        # TOML has no null: a field with no value (e.g. an unmapped area) is left out.
        lines += [f"{field} = {_quote(spec_class[field])}" for field in _CLASS_FIELDS if spec_class[field] is not None]
        lines += ["", f"[{key}.features]"]
        lines += [f"{_quote(f['name'])} = {_quote(f['hash'])}" for f in spec_class["features"]]
    return "\n".join(lines) + "\n"


def loads_manifest(text: str) -> dict:
    raw = tomllib.loads(text)
    excluded_classes = raw.pop("excluded_classes")
    upstream = raw.pop("upstream")
    classes = [
        {
            "key": key,
            **{field: table.get(field) for field in _CLASS_FIELDS},
            "features": [{"name": name, "hash": h} for name, h in table.get("features", {}).items()],
        }
        for key, table in raw.items()
    ]
    return {"upstream": upstream, "classes": classes, "excluded": {"classes": excluded_classes}}


def load_manifest(path: Path | None = None) -> dict:
    return loads_manifest((path or MANIFEST_PATH).read_text())
